fn rnd(x:f64)i64{const z=x*1000.0;return if(z>=0) @intFromFloat(z+0.5) else -@as(i64,@intFromFloat(-z+0.5));}
export fn liang_barsky(v:[*]const i64,n:usize)callconv(.c)i64{if(n!=8)return -1;for(0..8)|i|{if(v[i] < -5 or v[i]>5)return -1;}const xmin=@as(f64,@floatFromInt(v[0]));const ymin=@as(f64,@floatFromInt(v[1]));const xmax=@as(f64,@floatFromInt(v[2]));const ymax=@as(f64,@floatFromInt(v[3]));const x0=@as(f64,@floatFromInt(v[4]));const y0=@as(f64,@floatFromInt(v[5]));const x1=@as(f64,@floatFromInt(v[6]));const y1=@as(f64,@floatFromInt(v[7]));if(xmin>=xmax or ymin>=ymax)return -1;const dx=x1-x0;const dy=y1-y0;const p=[_]f64{-dx,dx,-dy,dy};const q=[_]f64{x0-xmin,xmax-x0,y0-ymin,ymax-y0};var t0:f64=0;var t1:f64=1;for(0..4)|i|{const t=q[i]/p[i];if(p[i]==0 and q[i]<0)return -1 else if(p[i]<0){if(t>t1)return -1;if(t>t0)t0=t;}else if(p[i]>0){if(t<t0)return -1;if(t<t1)t1=t;}}const z=[_]f64{x0+t0*dx,y0+t0*dy,x0+t1*dx,y0+t1*dy};var r:i64=0;for(z)|x|{r=r*10001+rnd(x)+5000;}return r;}
